// Parser CSV mínimo (soporta comillas). Devuelve array de objetos usando la fila 1 como cabeceras.
const parseCsv = (texto) => {
  const filas = []; let fila = [], celda = '', dentro = false;
  const s = String(texto ?? '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (dentro) {
      if (c === '"' && s[i + 1] === '"') { celda += '"'; i++; }
      else if (c === '"') dentro = false;
      else celda += c;
    } else if (c === '"') dentro = true;
    else if (c === ',') { fila.push(celda); celda = ''; }
    else if (c === '\n') { fila.push(celda); filas.push(fila); fila = []; celda = ''; }
    else if (c !== '\r') celda += c;
  }
  if (celda !== '' || fila.length) { fila.push(celda); filas.push(fila); }
  const [cab, ...datos] = filas.filter((f) => f.some((x) => x !== ''));
  return (datos ?? []).map((f) => Object.fromEntries(cab.map((h, i) => [h.trim().toLowerCase(), (f[i] ?? '').trim()])));
};
const num = (v) => { const n = parseFloat(String(v).replace(',', '.')); return isFinite(n) ? n : 0; };

export const code = async (inputs) => {
  const base = inputs.entorno === 'produccion' ? 'https://api.tradier.com' : 'https://sandbox.tradier.com';
  const headers = { Authorization: 'Bearer ' + inputs.tradierToken, Accept: 'application/json' };
  const get = async (ruta) => (await fetch(base + ruta, { headers })).json();

  // Simbolo OCC: TICKER + AAMMDD + C + strike*1000 con 8 digitos
  const occ = (t, venc, strike) => {
    const d = new Date(venc + 'T00:00:00Z');
    const p2 = (n) => String(n).padStart(2, '0');
    return t.toUpperCase() + String(d.getUTCFullYear()).slice(2) + p2(d.getUTCMonth() + 1) + p2(d.getUTCDate()) +
      'C' + String(Math.round(strike * 1000)).padStart(8, '0');
  };

  const posiciones = parseCsv(inputs.posicionesCsv).filter((p) => String(p.call_abierto).toLowerCase() === 'si');
  if (!posiciones.length) return { hayAlertas: false, resumen: 'Sin calls abiertos.' };

  const alertas = [], estado = [];
  for (const p of posiciones) {
    const ticker = String(p.ticker).toUpperCase();
    const strike = num(p.strike), prima = num(p.prima_cobrada);
    try {
      const q = await get('/v1/markets/quotes?symbols=' + ticker + ',' + occ(ticker, p.vencimiento, strike) + '&greeks=false');
      const cotiz = [].concat(q?.quotes?.quote ?? []);
      const accion = cotiz.find((x) => x.symbol === ticker);
      const opcion = cotiz.find((x) => x.symbol !== ticker);
      const precio = accion?.last ?? 0;
      const marca = opcion ? (opcion.bid + opcion.ask) / 2 : null;
      const capturado = marca !== null && prima > 0 ? (prima - marca) / prima : null;

      estado.push(ticker + ': accion $' + precio.toFixed(2) + ' | strike ' + strike +
        (capturado !== null ? ' | prima capturada ' + (capturado * 100).toFixed(0) + '%' : ''));

      // Regla 5.1: recomprar al capturar 50-70% de la prima
      if (capturado !== null && capturado >= 0.5)
        alertas.push('RECOMPRA ' + ticker + ': capturaste ' + (capturado * 100).toFixed(0) + '% de la prima. Cierra y libera la posicion.');
      // Regla 5.2: strike amenazado -> roll por credito o aceptar asignacion
      if (precio >= strike * 0.98)
        alertas.push('STRIKE AMENAZADO ' + ticker + ': accion $' + precio.toFixed(2) + ' vs strike ' + strike +
          '. Decide: roll por credito neto (si quieres las acciones) o dejar asignar.');
    } catch (e) {
      alertas.push(ticker + ': error consultando cotizaciones (' + e.message + ').');
    }
  }

  const resumen = (alertas.length ? 'ACCIONES REQUERIDAS:\n' + alertas.join('\n') + '\n\n' : '') +
    'Estado:\n' + estado.join('\n');
  return { hayAlertas: alertas.length > 0, resumen };
};
